-- ── TeamCoach: coaches / teams / roster / snapshots ─────────────────────────

CREATE TABLE coaches (
    id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name             TEXT NOT NULL,
    email            TEXT UNIQUE NOT NULL,
    auth_provider_id TEXT NULL,
    password_hash    TEXT NULL,
    salt             TEXT NULL,
    created_at       TEXT DEFAULT sqlite_now()
);

CREATE TABLE teams (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          TEXT NOT NULL,
    season        TEXT NOT NULL,
    club_id       INTEGER NULL,
    threshold_pct INTEGER NOT NULL DEFAULT 80,
    created_at    TEXT DEFAULT sqlite_now()
);

CREATE TABLE coach_team_access (
    coach_id INTEGER NOT NULL REFERENCES coaches(id),
    team_id  INTEGER NOT NULL REFERENCES teams(id),
    PRIMARY KEY (coach_id, team_id)
);

CREATE TABLE roster_membership (
    id                  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    athlete_id          INTEGER NOT NULL REFERENCES athletes(id),
    team_id             INTEGER NOT NULL REFERENCES teams(id),
    parent_consent_flag INTEGER NOT NULL DEFAULT 0,
    joined_at           TEXT DEFAULT sqlite_now(),
    UNIQUE (athlete_id, team_id)
);

CREATE TABLE team_engagement_snapshot (
    id                      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    team_id                 INTEGER NOT NULL REFERENCES teams(id),
    week_start              TEXT NOT NULL,
    threshold_pct           INTEGER NOT NULL DEFAULT 80,
    players_above_threshold INTEGER NOT NULL DEFAULT 0,
    roster_count            INTEGER NOT NULL DEFAULT 0,
    generated_at            TEXT DEFAULT sqlite_now(),
    UNIQUE (team_id, week_start)
);


-- ── Admin / health / observability ──────────────────────────────────────────

CREATE TABLE admin_audit_log (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_id     INTEGER NOT NULL,
    actor_email  TEXT NOT NULL,
    actor_role   TEXT NOT NULL,
    action       TEXT NOT NULL,
    target_type  TEXT NOT NULL,
    target_id    INTEGER NOT NULL,
    target_email TEXT,
    before_state TEXT,
    after_state  TEXT,
    request_ip   TEXT,
    user_agent   TEXT,
    created_at   TEXT NOT NULL DEFAULT sqlite_now()
);
CREATE INDEX idx_admin_audit_created ON admin_audit_log(created_at);

CREATE TABLE health_checks (
    check_name      TEXT PRIMARY KEY,
    status          TEXT NOT NULL DEFAULT 'unknown',
    detail          TEXT,
    metric_value    DOUBLE PRECISION,
    last_checked_at TEXT,
    last_green_at   TEXT,
    last_red_at     TEXT,
    last_alerted_at TEXT
);

CREATE TABLE health_incidents (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    check_name  TEXT NOT NULL,
    from_status TEXT,
    to_status   TEXT,
    detail      TEXT,
    created_at  TEXT NOT NULL DEFAULT sqlite_now()
);
CREATE INDEX idx_health_incidents_check ON health_incidents(check_name, created_at);
CREATE INDEX idx_health_incidents_created ON health_incidents(created_at);

CREATE TABLE health_scratch (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    v  TEXT
);

CREATE TABLE scheduler_heartbeats (
    job_name        TEXT PRIMARY KEY,
    last_run_at     TEXT,
    last_success_at TEXT,
    last_error      TEXT,
    meta            TEXT
);
